/**
 * DEVELOPMENT ONLY. Illustrative civic data so place, leader and bill pages
 * can be designed before real data ingestion (Phases 3-4) exists.
 *
 * Honesty rules for this file:
 * - Every row is flagged `is_sample = true`; the UI shows a "Sample data"
 *   banner on it and production refuses to start while any sample row exists.
 * - Leaders are FICTIONAL people (made-up names). No real person is scored.
 * - All numbers are generated by a seeded pseudo-random generator. They are
 *   NOT real statistics about any real place. Sources are listed only as
 *   "planned source" labels, with no URL, so nothing implies a real source
 *   published these numbers.
 * - Place names (states, counties, cities, court districts) are real
 *   geography so navigation can be tested realistically.
 */

/** Small deterministic PRNG (mulberry32), so the sample data is stable. */
function rng(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = rng(20261110);
const between = (lo: number, hi: number) => lo + (hi - lo) * rand();
const int = (lo: number, hi: number) => Math.round(between(lo, hi));
const pick = <T>(list: readonly T[]): T => list[Math.floor(rand() * list.length)]!;
const clampScore = (n: number) => Math.max(3, Math.min(97, Math.round(n)));

