function placeRationale(
  place: string,
  kind: string,
  category: string,
  slug: string,
  score: number,
) {
  const [a, b] = DRIVERS[slug] ?? genericDrivers(category);
  const tone =
    score >= 65 ? 'better than most' : score >= 40 ? 'close to the middle of' : 'worse than most';
  return (
    `SAMPLE EXPLANATION (illustrative, not real data). ${place} scores ${score}/100 in ${category}, ` +
    `${tone} other ${PEER_WORD[kind] ?? 'places'}. The score combines how ${place} compares with its peers on ` +
    `${a} and ${b}; each indicator is turned into a percentile among peers, and the category score is their average. ` +
    `On a real page, each indicator below would show its value, data year and official source.`
  );
}

function leaderRationale(name: string, category: string, score: number, n: number) {
  const tone =
    score >= 65
      ? 'mostly kept their stated positions'
      : score >= 40
        ? 'had a mixed record'
        : 'often acted against their stated positions';
  return (
    `SAMPLE EXPLANATION (illustrative; this is a fictional leader). In ${category}, ${name} ${tone}, ` +
    `based on ${n} rated citations. Positive and negative citations are weighted by how accurate members rated them, ` +
    `older citations fade over time, and positive citations count only after a streak (docs/SCORING.md). ` +
    `On a real page, each citation below would link to its source and show its accuracy votes.`
  );
}

