const isoDaysAgo = (n: number) =>
  new Date(Date.UTC(2026, 10, 10) - n * 86_400_000).toISOString().slice(0, 10);

export async function seedSampleCivic(
  pool: Pool,
): Promise<{ skipped: boolean; leaders: number; bills: number }> {
  const { rows: already } = await pool.query<{ n: number }>(
    'SELECT count(*)::int AS n FROM leaders WHERE is_sample',
  );
  if ((already[0]?.n ?? 0) > 0) return { skipped: true, leaders: 0, bills: 0 };

  const { rows: refPlaces } = await pool.query<{
    id: string;
    slug: string;
    name: string;
    kind: string;
  }>('SELECT id, slug, name, kind FROM places WHERE NOT is_sample');
  const placeBySlug = new Map(refPlaces.map((p) => [p.slug, p]));
  const { rows: cats } = await pool.query<{ id: string; slug: string; name: string }>(
    "SELECT id, slug, name FROM communities WHERE kind = 'topic' ORDER BY name",
  );
  const catBySlug = new Map(cats.map((c) => [c.slug, c]));
  // Only score categories that apply to a subject's level of government.
  const { rows: levelRows } = await pool.query<{ category_id: string; level: string }>(
    'SELECT category_id, level FROM category_levels',
  );
  const applies = (categoryId: string, level: string | undefined) =>
    levelRows.some((r) => r.category_id === categoryId && r.level === level);

  // Sub-places (sample rows; real geography names).
  for (const p of SUB_PLACES) {
    const { rows } = await pool.query<{ id: string }>(
      `INSERT INTO places (slug, name, kind, parent_id, population, is_sample)
       VALUES ($1, $2, $3, $4, $5, true) RETURNING id`,
      [p.slug, p.name, p.kind, placeBySlug.get(p.state)!.id, p.population ?? null],
    );
    placeBySlug.set(p.slug, { id: rows[0]!.id, slug: p.slug, name: p.name, kind: p.kind });
  }
  const allPlaces = [...placeBySlug.values()];

  // Fictional leaders.
  const used = new Set<string>();
  const fictionalName = () => {
    for (;;) {
      const n = `${pick(FIRST)} ${pick(LAST)}`;
      if (!used.has(n)) {
        used.add(n);
        return n;
      }
    }
  };
  const leaders: Array<{ id: string; name: string; party: string; place: string; kind: string }> =
    [];
  const addLeader = async (office: string, kind: string, placeSlug: string) => {
    const name = fictionalName();
    const party = pick(PARTIES);
    const slug = `${name.toLowerCase().replace(/[^a-z]+/g, '-')}-sample`;
    const { rows } = await pool.query<{ id: string }>(
      `INSERT INTO leaders (slug, name, office, office_kind, party, place_id, bio, is_sample)
       VALUES ($1, $2, $3, $4, $5, $6, $7, true) RETURNING id`,
      [
        slug,
        name,
        office,
        kind,
        party,
        placeBySlug.get(placeSlug)!.id,
        `Fictional sample leader used to design Demanity. ${name} is not a real person.`,
      ],
    );
    leaders.push({ id: rows[0]!.id, name, party, place: placeSlug, kind });
  };
  await addLeader('President of the United States', 'president', 'united-states');
  for (const s of STATES) {
    await addLeader(`Governor of ${STATE_NAMES[s]}`, 'governor', s);
    await addLeader(`U.S. Senator for ${STATE_NAMES[s]}`, 'us_senate', s);
    await addLeader(`U.S. Senator for ${STATE_NAMES[s]}`, 'us_senate', s);
    await addLeader(`U.S. Representative, ${STATE_NAMES[s]}`, 'us_house', s);
    await addLeader(`U.S. Representative, ${STATE_NAMES[s]}`, 'us_house', s);
    await addLeader(`State Senator, ${STATE_NAMES[s]}`, 'state_senate', s);
  }
  for (const p of SUB_PLACES.filter((x) => x.kind === 'city'))
    await addLeader(`Mayor of ${p.name}`, 'mayor', p.slug);
  for (const p of SUB_PLACES.filter((x) => x.kind === 'county'))
    await addLeader(`${p.name} Executive`, 'county_executive', p.slug);

  // Category scores for every place and leader, all 32 categories.
  const asOf = '2026-11-01';
  for (const p of allPlaces) {
    const base = between(38, 66);
    const scores: Array<{ slug: string; score: number }> = [];
    for (const c of cats) {
      if (!applies(c.id, PLACE_LEVEL[p.kind])) continue; // e.g. no foreign policy for cities
      const score = clampScore(base + between(-30, 30));
      const n = int(1, 8); // indicators behind the score
      scores.push({ slug: c.slug, score });
      await pool.query(
        `INSERT INTO category_scores (subject_type, subject_id, category_id, score, rationale, evidence,
                                      evidence_count, method_version, as_of, is_sample)
         VALUES ('place', $1, $2, $3, $4, $5, $6, 'places-v0-sample', $7, true)`,
        [
          p.id,
          c.id,
          score,
          placeRationale(p.name, p.kind, c.name, c.slug, score),
          JSON.stringify(
            (DRIVERS[c.slug] ?? genericDrivers(c.name)).map((d) => ({
              label: `Sample indicator: ${d} (planned source: ${PLANNED_SOURCE[c.slug] ?? 'to be mapped'})`,
              url: null,
            })),
          ),
          n,
          asOf,
        ],
      );
    }
    // Most pressing issues = the 3 lowest-scoring categories.
    const worst = [...scores].sort((a, b) => a.score - b.score).slice(0, 3);
    for (const [i, w] of worst.entries()) {
      const c = catBySlug.get(w.slug)!;
      const [driver] = DRIVERS[w.slug] ?? genericDrivers(c.name);
      await pool.query(
        `INSERT INTO place_issues (place_id, rank, category_id, title, summary, source_label, is_sample)
         VALUES ($1, $2, $3, $4, $5, $6, true)`,
        [
          p.id,
          i + 1,
          c.id,
          c.name,
          `Sample: ${p.name} scores ${w.score}/100 here, one of its weakest areas compared with other ${PEER_WORD[p.kind] ?? 'places'}, driven by the ${driver}.`,
          'Sample · ranked from the lowest category scores',
        ],
      );
    }
    if (p.kind !== 'court_district') {
      for (const s of STAT_DEFS) {
        const raw = between(...s.range);
        const value =
          s.unit === 'usd' || s.unit === 'percent' ? Math.round(raw * 10) / 10 : Math.round(raw);
        await pool.query(
          `INSERT INTO place_stats (place_id, key, label, value, unit, higher_is_better, source_label, as_of, is_sample)
           VALUES ($1, $2, $3, $4, $5, $6, $7, $8, true)`,
          [
            p.id,
            s.key,
            s.label,
            value,
            s.unit,
            s.higher,
            `Sample · planned source: ${s.source}`,
            asOf,
          ],
        );
      }
    }
    const elections: Array<[string, string, string]> =
      p.kind === 'state' || p.kind === 'nation'
        ? [
            ['general', 'U.S. President, Congress and statewide offices', '2028-11-07'],
            ['primary', 'Primary election', '2028-03-07'],
          ]
        : p.kind === 'city'
          ? [['general', `Mayor of ${p.name}`, '2027-11-02']]
          : p.kind === 'county'
            ? [['general', 'County executive and commissioners', '2028-11-07']]
            : [];
    for (const [kind, office, date] of elections) {
      const { rows: e } = await pool.query<{ id: string }>(
        `INSERT INTO elections (place_id, office, kind, election_date, source_label, is_sample)
         VALUES ($1, $2, $3, $4, 'Sample · planned source: state election office', true) RETURNING id`,
        [p.id, office, kind, date],
      );
      // Fictional candidates, one per party.
      for (const party of PARTIES) {
        await pool.query(
          'INSERT INTO election_candidates (election_id, name, party, is_sample) VALUES ($1, $2, $3, true)',
          [e[0]!.id, fictionalName(), party],
        );
      }
    }
  }

  for (const l of leaders) {
    for (const c of cats) {
      if (!applies(c.id, OFFICE_LEVEL[l.kind])) continue; // mayors do not run foreign policy
      const n = int(0, 14); // rated citations
      if (n === 0) continue; // not scored yet in this category
      const score = clampScore(between(20, 85));
      await pool.query(
        `INSERT INTO category_scores (subject_type, subject_id, category_id, score, rationale, evidence,
                                      evidence_count, method_version, as_of, is_sample)
         VALUES ('leader', $1, $2, $3, $4, $5, $6, 'scoring-v1-sample', $7, true)`,
        [
          l.id,
          c.id,
          score,
          leaderRationale(l.name, c.name, score, n),
          JSON.stringify([
            {
              label: `Sample citation: voted on a ${c.name.toLowerCase()} bill (rated accurate by 78%)`,
              url: null,
            },
            {
              label: `Sample citation: public statement on ${c.name.toLowerCase()} (rated accurate by 64%)`,
              url: null,
            },
          ]),
          n,
          asOf,
        ],
      );
    }
  }

  // Bills: federal ones sponsored by members of Congress, state ones by state officials.
  let bills = 0;
  for (const [i, idea] of BILL_IDEAS.entries()) {
    const federal = i % 2 === 0;
    const state = STATES[i % STATES.length]!;
    const jurisdiction = federal ? 'united-states' : state;
    const pool_ = leaders.filter((l) =>
      federal
        ? l.kind === 'us_senate' || l.kind === 'us_house'
        : l.place === state && l.kind !== 'us_senate' && l.kind !== 'us_house',
    );
    const status = STATUSES[i % STATUSES.length]!;
    const introduced = int(20, 300);
    const { rows } = await pool.query<{ id: string }>(
      `INSERT INTO bills (place_id, number, title, summary, category_id, status, introduced_at, last_action_at, impact, is_sample)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, true) RETURNING id`,
      [
        placeBySlug.get(jurisdiction)!.id,
        federal ? `H.R. ${9000 + i} (sample)` : `SB ${700 + i} (sample)`,
        `[Sample] ${idea.title}`,
        `Sample bill. ${idea.summary}`,
        catBySlug.get(idea.category)?.id ?? null,
        status,
        isoDaysAgo(introduced),
        isoDaysAgo(int(1, introduced)),
        `Sample: ${IMPACTS[i % IMPACTS.length]}`,
      ],
    );
    const billId = rows[0]!.id;
    const sponsor = pick(pool_);
    await pool.query(
      "INSERT INTO bill_sponsors (bill_id, leader_id, role) VALUES ($1, $2, 'sponsor')",
      [billId, sponsor.id],
    );
    // Half the bills get a cosponsor from another party (common ground).
    const other = pool_.find(
      (l) => l.id !== sponsor.id && (i % 2 === 0 ? l.party !== sponsor.party : true),
    );
    if (other)
      await pool.query(
        "INSERT INTO bill_sponsors (bill_id, leader_id, role) VALUES ($1, $2, 'cosponsor')",
        [billId, other.id],
      );
    bills++;
  }

  // A few sample requests, written by the dev moderators.
  const { rows: authors } = await pool.query<{ id: string }>(
    'SELECT account_id AS id FROM dev_seed_accounts ORDER BY created_at LIMIT 2',
  );
  const governor = leaders.find((l) => l.kind === 'governor')!;
  const senator = leaders.find((l) => l.kind === 'us_senate')!;
  const asks: Array<[string, string, string]> = [
    [
      governor.id,
      '[Sample] Hold a town hall in every county this year',
      'Sample request: meet people where they live.',
    ],
    [governor.id, '[Sample] Publish your weekly schedule', 'Sample request for transparency.'],
    [senator.id, '[Sample] Explain your vote on the bridge repair bill', 'Sample request.'],
  ];
  // Illustrate the accountability loop: one awaiting a response past the
  // vote threshold, one answered by the leader, one simply open.
  const lifecycle: Array<{
    status: string;
    response: string | null;
    thresholdDaysAgo: number | null;
  }> = [
    { status: 'open', response: null, thresholdDaysAgo: 12 },
    {
      status: 'responded',
      response:
        'Sample response from the leader: the weekly schedule will be posted every Monday starting next month.',
      thresholdDaysAgo: 30,
    },
    { status: 'open', response: null, thresholdDaysAgo: null },
  ];
  for (const [i, [leaderId, title, body]] of asks.entries()) {
    const author = authors[i % Math.max(authors.length, 1)]?.id ?? null;
    const life = lifecycle[i]!;
    const { rows } = await pool.query<{ id: string }>(
      `INSERT INTO leader_requests (leader_id, author_id, title, body, status, response, responded_at, threshold_reached_at)
       VALUES ($1, $2, $3, $4, $5, $6::text,
               CASE WHEN $6::text IS NULL THEN NULL ELSE now() - interval '3 days' END,
               CASE WHEN $7::int IS NULL THEN NULL ELSE now() - make_interval(days => $7::int) END)
       RETURNING id`,
      [leaderId, author, title, body, life.status, life.response, life.thresholdDaysAgo],
    );
    for (const a of authors.slice(0, authors.length - i))
      await pool.query(
        'INSERT INTO leader_request_votes (account_id, request_id) VALUES ($1, $2)',
        [a.id, rows[0]!.id],
      );
  }

  await recomputeRollups(pool);
  return { skipped: false, leaders: leaders.length, bills };
}

/**
 * Deletes all sample data (pre-launch cleanup; also used by tests). Real rows
 * are untouched. Order matters because of foreign keys.
 */
export async function clearSampleData(pool: Pool): Promise<void> {
  await pool.query("DELETE FROM leader_requests WHERE title LIKE '[Sample]%'");
  await pool.query("DELETE FROM posts WHERE title LIKE '[Sample]%'");
  await pool.query('DELETE FROM bills WHERE is_sample');
  await pool.query('DELETE FROM category_scores WHERE is_sample');
  await pool.query('DELETE FROM place_stats WHERE is_sample');
  await pool.query('DELETE FROM place_issues WHERE is_sample');
  await pool.query('DELETE FROM elections WHERE is_sample');
  await pool.query('DELETE FROM leaders WHERE is_sample');
  await pool.query('DELETE FROM places WHERE is_sample');
  await pool.query('DELETE FROM guides WHERE is_sample');
  await recomputeRollups(pool);
}
